# Let me manually identify the transformations needed
inputs = ['zau', 'iebcvv', 'kfaxc', 'vz', 'hwa']
outputs = ['zwuu', 'iebcvv', 'kfwukic', 'vz', 'hwwu']

# Analyze each pair
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{out}'")

    # Let's look at differences
    if inp != out:
        # Find what changed
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Length change: {len(inp)} -> {len(out)}")
    else:
        print("  No change")
    print()

